<?php
namespace Tests\Feature;
use App\Models\User;
use App\Modules\Tenancy\Models\Officine;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Crypt;
use Laravel\Sanctum\Sanctum;
use Tests\TestCase;
class SocleManagementTest extends TestCase {
 use RefreshDatabase;
 private User $admin;private Officine $office;
 protected function setUp():void{parent::setUp();$this->admin=User::create(['name'=>'Admin','email'=>'admin@example.test','password'=>'Fictional12345']);$this->office=Officine::create(['name'=>'Fictive','slug'=>'fictive','status'=>'active']);DB::table('officine_user')->insert(['officine_id'=>$this->office->id,'user_id'=>$this->admin->id,'is_admin'=>true,'is_active'=>true,'permissions'=>'[]']);Sanctum::actingAs($this->admin);$this->withHeader('X-Officine-ID',(string)$this->office->id);}
 public function test_role_duplicate_is_unassigned_and_deactivation_requires_reassignment():void{$id=$this->postJson('/api/v1/team/roles',['name'=>'Viewer','description'=>'Lecture','permissions'=>['qualite.read']])->assertCreated()->json('id');$copy=$this->postJson('/api/v1/team/roles/'.$id.'/duplicate',['name'=>'Copy'])->assertCreated()->json('id');$this->assertDatabaseMissing('officine_member_roles',['role_id'=>$copy]);$membership=DB::table('officine_user')->value('id');DB::table('officine_member_roles')->insert(['membership_id'=>$membership,'role_id'=>$id]);$this->postJson('/api/v1/team/roles/'.$id.'/state',['is_active'=>false,'version'=>1])->assertConflict();$this->postJson('/api/v1/team/roles/'.$copy.'/state',['is_active'=>false,'version'=>1])->assertOk();$this->postJson('/api/v1/team/invitations',['email'=>'i@example.test','role_ids'=>[$copy],'is_admin'=>false])->assertUnprocessable();$this->postJson('/api/v1/team/roles/'.$copy.'/state',['is_active'=>true,'version'=>1])->assertConflict();}
 public function test_invitation_resend_invalidates_previous_secret_and_queues_encrypted_delivery():void{$old=$this->postJson('/api/v1/team/invitations',['email'=>'invite@example.test','role_ids'=>[],'is_admin'=>false])->assertCreated()->json('invite_token');$id=DB::table('officine_invitations')->value('id');$fresh=$this->postJson('/api/v1/team/invitations/'.$id.'/resend')->assertOk()->json('invite_token');$this->assertNotSame($old,$fresh);$this->assertDatabaseMissing('officine_invitations',['token'=>hash('sha256',$old)]);$this->assertDatabaseHas('officine_invitations',['token'=>hash('sha256',$fresh)]);$this->assertStringNotContainsString($fresh,json_encode(DB::table('notification_outbox')->get()));}
 public function test_platform_state_changes_require_version_and_cut_access_without_deleting():void{$this->postJson('/api/v1/platform/officines/'.$this->office->id.'/state',['status'=>'suspended','version'=>1,'reason'=>'Test'])->assertForbidden();$review=User::create(['name'=>'Reviewer','email'=>'review@example.test','password'=>'Fictional12345']);$review->forceFill(['is_platform_admin'=>true])->save();Sanctum::actingAs($review);$url='/api/v1/platform/officines/'.$this->office->id.'/state';$this->postJson($url,['status'=>'archived','version'=>1,'reason'=>'Archivage fictif'])->assertOk();$this->postJson($url,['status'=>'active','version'=>2,'reason'=>'Trop direct'])->assertConflict();$this->postJson($url,['status'=>'suspended','version'=>2,'reason'=>'Restauration'])->assertOk();Sanctum::actingAs($this->admin);$this->getJson('/api/v1/officine')->assertForbidden();$this->assertDatabaseHas('officine_user',['officine_id'=>$this->office->id]);}
 public function test_internal_invite_requires_acceptance_and_disabling_does_not_suspend_personal_account():void{$this->admin->forceFill(['is_platform_admin'=>true])->save();Sanctum::actingAs($this->admin);$this->postJson('/api/v1/platform/internal-team/invitations',['email'=>'staff@example.test','staff'=>true,'coordinator'=>false])->assertCreated();$this->assertDatabaseMissing('users',['email'=>'staff@example.test']);$row=DB::table('notification_outbox')->where('title','Invitation à l’équipe d’accompagnement')->first();$body=json_decode(Crypt::decryptString($row->encrypted_message),true)['body'];preg_match('/token=([A-Za-z0-9]{64})/',$body,$m);$this->app['auth']->forgetGuards();$d=['token'=>$m[1],'email'=>'staff@example.test','name'=>'Staff fictif','password'=>'Fictional12345','password_confirmation'=>'Fictional12345'];$this->postJson('/api/v1/internal-invitations/accept',$d)->assertCreated();$u=User::where('email','staff@example.test')->firstOrFail();$this->assertTrue($u->is_support_staff);$this->postJson('/api/v1/internal-invitations/accept',$d)->assertUnprocessable();Sanctum::actingAs($this->admin);$this->putJson('/api/v1/platform/internal-team/'.$u->id,['version'=>$u->internal_version,'internal_active'=>false,'reason'=>'Fin de collaboration'])->assertOk();$this->assertFalse($u->fresh()->internal_active);$this->assertTrue($u->fresh()->is_active);}
 public function test_existing_internal_invitee_must_authenticate_before_association():void{$u=User::create(['name'=>'Existing','email'=>'existing@example.test','password'=>'Fictional12345']);$this->admin->forceFill(['is_platform_admin'=>true])->save();Sanctum::actingAs($this->admin);$this->postJson('/api/v1/platform/internal-team/invitations',['email'=>$u->email,'staff'=>true,'coordinator'=>true])->assertCreated();$row=DB::table('notification_outbox')->where('title','Invitation à l’équipe d’accompagnement')->first();preg_match('/token=([A-Za-z0-9]{64})/',json_decode(Crypt::decryptString($row->encrypted_message),true)['body'],$m);$this->postJson('/api/v1/internal-invitations/accept',['token'=>$m[1],'email'=>$u->email])->assertUnprocessable();Sanctum::actingAs($u);$this->postJson('/api/v1/internal-invitations/accept',['token'=>$m[1],'email'=>$u->email])->assertCreated();$this->assertFalse($u->fresh()->is_platform_admin);}
}
